Follow this complete example.
```swift
struct Duration {
    var seconds: Double
    var minutes: Double {
        get { return seconds / 60 }
        set { seconds = newValue * 60 }
    }
}
var duration = Duration(seconds: 90)
print(duration.minutes)
duration.minutes = 2.5
print(duration.seconds)
```
Output:
```text
1.5
150.0
```

